export function Faq({ locale = "en" }: { locale?: Locale }) {
  const items = locale === "en" ? faqItems : localizedFaqs[locale];
  return (
    <section className="result-wrap faq-page" aria-labelledby="faq-title">
      <div className="result-heading">
        <div className="eyebrow">{translate(locale, "Help and information")}</div>
        <h1 id="faq-title" tabIndex={-1}>{translate(locale, "Frequently asked questions")}</h1>
        <p>{translate(locale, "Learn about the ALSO Security Policy Templates Navigator, our templates, and deployment tools.")}</p>
      </div>
      <div className="faq-list">
        {items.map(({ question, answer }, index) => (
          <details className="faq-item" key={question}>
            <summary>
              <span className="faq-number">{String(index + 1).padStart(2, "0")}</span>
              <span>{question}</span>
              <span className="faq-chevron" aria-hidden="true" />
            </summary>
            <div className="faq-answer">
              {answer.map((paragraph, paragraphIndex) => (
                <Fragment key={paragraphIndex}>
                  {typeof paragraph === "string" ? <p>{paragraph}</p> : paragraph}
                </Fragment>
              ))}
            </div>
          </details>
        ))}
      </div>
    </section>
  );
}
